  1	\chapter{The Pauli basis test}
  2	\label{chap:qpbt-test}
  3	% Paper label sec:pauli-verifier kept for cross-reference fidelity; it resolves to this chapter.
  4	\label{sec:pauli-verifier}
  5	
  6	This chapter defines the two testing primitives underlying the question-reduction step: the \emph{classical low individual degree game}, in its simultaneous form, and the \emph{Pauli basis test}, a nonlocal game built from the classical game together with the Magic Square game. We state the quantum soundness of the classical game (Theorem~\ref{lem:ld-soundness}, imported, with the facts required by the identification, which remain to be proved, recorded in \cite{gap:qpbt_ld-dimension-divisibility}; see Remark~\ref{rem:ld-soundness-provider}), the rigidity of the Magic Square game (Theorem~\ref{thm:ms-rigidity}, imported), completeness of the Pauli basis test (Lemma~\ref{lem:pauli-completeness}), and the main soundness theorem for the Pauli basis test (Theorem~\ref{thm:pauli}), whose proof occupies Chapters~\ref{chap:qpbt-observables}--\ref{chap:qpbt-extraction} and is completed in Chapter~\ref{chap:qpbt-extraction} only modulo the proof obligation documented in \cite{gap:qpbt_ld-dimension-divisibility}. The chapter closes with the qubit form of the soundness statement (Corollary~\ref{cor:pauli-binary}) and the canonical parameter choice with its soundness bound (Definition~\ref{def:introparams}, Lemma~\ref{lem:delta-bound}).
  7	
  8	Throughout, the two players are denoted $\mathrm A$ and $\mathrm B$; for $w \in \{\mathrm A,\mathrm B\}$ we write $\overline w$ for the other player. Games, strategies, values, conditionally linear (CL) functions and distributions, typed distributions sampled from the edges of a graph, and the state-dependent approximation $\approx_\delta$ between families of measurement operators are as in Chapter~\ref{chap:qpbt-games}; the algebraic material on lines, canonical linear maps, the low-degree encoding, and generalized Pauli observables is from Chapter~\ref{chap:qpbt-algebra}.
  9	
 10	\section{The classical low individual degree game}
 11	% Paper labels sec:ld-verifier and sec:ld-game kept for cross-reference fidelity.
 12	\label{sec:ld-verifier}
 13	\label{sec:ld-game}
 14	
 15	The classical low individual degree game is a two-player game based on the low individual degree variant of the multilinearity test of Babai, Fortnow, and Lund. In the basic version, one player (the ``points player'') receives a uniformly random point $u \in \F_q^m$ and answers with a value $a \in \F_q$, while the other player (the ``lines player'') receives a random line through $u$ --- either axis-parallel or diagonal --- and answers with a univariate polynomial describing the restriction of a global function to that line. If the players share a polynomial $g\colon \F_q^m \to \F_q$ of individual degree at most $d$ and answer with $g(u)$ and with the restriction $g|_\ell$, they win with probability $1$; the soundness theorem below states that the converse approximately holds. In the simultaneous version, the players' answers are $k$-tuples, checked coordinatewise against a $k$-tuple of low individual degree polynomials.
 16	
 17	\begin{definition}[The classical low individual degree game: parameters and registers]\label{def:ld-game}
 18		\lean{MIPStarRE.QPBT.ldGame}
 19		\uses{def:game, def:admissible-size}
 20		% The source fixes \N to be the set of positive integers
 21		% (references/qpbt-paper/04_preliminaries.tex:6) and takes m, d, ldc in \N
 22		% (references/qpbt-paper/08_classical_and_quantum_low_degree_tests.tex:33-35),
 23		% so the positivity below is the source's implicit domain, stated explicitly.
 24		% It is load-bearing: at d = 0 or k = 0 the prefactor a(dmk)^a of delta_ld in
 25		% lem:ld-soundness vanishes, and at d = 0 the resulting exact conclusions fail
 26		% (e.g. at (q,m,d,k) = (2,1,0,1) with eps = 1). The case k = 0, though it would
 27		% hold trivially, is likewise outside the source's domain and is omitted.
 28		The game $\mathfrak{G}^{\mathrm{ld}}$ is parametrized by a tuple $\mathsf{ldparams} = (q,m,d,k)$, where $m, d, k \ge 1$ are integers, $q \in \N$ is an admissible field size (Definition~\ref{def:admissible-size}), and $m$ divides $q$. We write $\mathfrak{G}^{\mathrm{ld}}_{\mathsf{ldparams}}$ to emphasize the dependence on the parameter tuple. The type set of $\mathfrak{G}^{\mathrm{ld}}$ is
 29		\[
 30			\mathcal T^{\mathrm{ld}} = \{\mathsf{Point}, \mathsf{ALine}, \mathsf{DLine}\}\;,
 31		\]
 32		and the distribution over type pairs $(t_{\mathrm A}, t_{\mathrm B})$ is uniform over $\mathcal T^{\mathrm{ld}} \times \mathcal T^{\mathrm{ld}}$. The ambient space is the direct sum $V = V_X \oplus V_I \oplus V_V$ of three register subspaces: the \emph{point register} $V_X \cong \F_q^m$, the \emph{coordinate register} $V_I \cong \F_q$, and the \emph{direction register} $V_V \cong \F_q^m$. Elements of $V$ are identified with triples $(u,s,v) \in \F_q^m \times \F_q \times \F_q^m$. The question distribution and the win predicate of $\mathfrak{G}^{\mathrm{ld}}$ are specified in Definitions~\ref{def:ld-question-distribution} and~\ref{def:ld-win-predicate} below.
 33	\end{definition}
 34	
 35	\begin{definition}[Question distribution of the classical low individual degree game]\label{def:ld-question-distribution}
 36		\uses{def:ld-game, def:cl-func, def:cl-dist, lem:cl-concat, def:cl-canonical, def:line-representative}
 37		Let $\mathsf{ldparams} = (q,m,d,k)$ be as in Definition~\ref{def:ld-game}. Define $L_{\mathsf{Point}}$ to be the $1$-level CL function on $V$ that projects onto $V_X$: for every $(u,s,v) \in V$,
 38		\begin{equation}
 39			\label{eq:cl-ptf}
 40			L_{\mathsf{Point}}(u,s,v) = (u,0,0)\;.
 41		\end{equation}
 42		For $s \in \F_q$, let $\chi(s)$ be the unique integer such that
 43		\begin{equation}
 44			\label{eq:chi-func}
 45			s = (\chi(s)-1)\,\frac{q}{m} + r
 46		\end{equation}
 47		for some $0 \le r < q/m$, where $s$ is interpreted as an integer in $\{0,1,\ldots,q-1\}$ under the identification of $\F_q$ with binary strings fixed in Chapter~\ref{chap:qpbt-algebra}. Since $m$ divides $q$, when $s$ is uniformly distributed on $\F_q$ the index $\chi(s)$ is uniformly distributed on $\{1,2,\ldots,m\}$. Define $L_{\mathsf{ALine}}$ by
 48		\begin{equation}
 49			\label{eq:cl-alnf}
 50			L_{\mathsf{ALine}}(u,s,v) = \bigl(L^{\mathrm{Ln}}_{e_i}(u),\, s,\, 0\bigr)\quad\text{for all } (u,s,v) \in V\;,
 51		\end{equation}
 52		where $i = \chi(s)$ and $L^{\mathrm{Ln}}_v$ denotes the canonical linear map with one-dimensional kernel spanned by $v$, used to compute canonical representatives of lines (Definition~\ref{def:line-representative}). The function $L_{\mathsf{ALine}}$ is the concatenation (in the sense of Lemma~\ref{lem:cl-concat}) of the $1$-level CL function projecting $V_I \oplus V_V$ onto $V_I$ with the family of $1$-level CL functions $\{L^{\mathrm{Ln}}_{e_i}\}$ on $V_X$ indexed by $i \in \{1,\ldots,m\}$; thus $L_{\mathsf{ALine}}$ is a $2$-level CL function. Define $L_{\mathsf{DLine}}$ by
 53		\begin{equation}
 54			\label{eq:cl-dlnf}
 55			L_{\mathsf{DLine}}(u,s,v) = \bigl(L^{\mathrm{Ln}}_{\pi_{i-1}(v)}(u),\, s,\, \pi_{i-1}(v)\bigr)\;,
 56		\end{equation}
 57		where $i = \chi(s)$ and $\pi_{i-1}$ zeroes out the first $i-1$ coordinates of its input. The function $L_{\mathsf{DLine}}$ is the concatenation of (i) the identity on $V_I$, (ii) for each $i$ the $1$-level CL function $v \mapsto \pi_{i-1}(v)$ on $V_V$, and (iii) for each pair $(s,v') \in V_I \oplus V_V$ the $1$-level CL function $L^{\mathrm{Ln}}_{v'}$ on $V_X$; thus $L_{\mathsf{DLine}}$ is a $3$-level CL function.
 58	
 59		The question distribution of $\mathfrak{G}^{\mathrm{ld}}$ is the typed CL distribution obtained as follows: sample a type pair $(t_{\mathrm A}, t_{\mathrm B})$ uniformly from $\mathcal T^{\mathrm{ld}} \times \mathcal T^{\mathrm{ld}}$, sample $z = (u,s,v)$ uniformly from $V$, and send each player $w \in \{\mathrm A,\mathrm B\}$ the question $(t_w, L_{t_w}(z))$.
 60	\end{definition}
 61	
 62	The next two lemmas show that the CL functions $L_{\mathsf{Point}}$, $L_{\mathsf{ALine}}$, $L_{\mathsf{DLine}}$ give rise to the axis-parallel and diagonal line-versus-point distributions.
 63	We label the coordinates by $r\in\{0,\ldots,m-1\}$, with label $r$
 64	representing the paper's coordinate $r+1$.
 65	
 66	\begin{lemma}\label{lem:alnf}
 67		\lean{MIPStarRE.QPBT.aLinePointDist_point_marginal_uniform, MIPStarRE.QPBT.aLinePointDist_mem_line}
 68		\leanok
 69		\uses{def:ld-question-distribution, def:line}
 70		Consider the pair $(\ell, u)$ sampled in the following way: first, sample the tuple $\bigl((u_0,s,0),(u,0,0)\bigr)$ from the CL distribution $\mu_{L_{\mathsf{ALine}}, L_{\mathsf{Point}}}$, and let $\ell = \ell(u_0, e_i)$ where $i = \chi(s)$. Then $u$ is a uniformly random point in $\F_q^m$, and $\ell$ is a line that goes through $u$ and is parallel to a uniformly random axis $i \in \{1,2,\ldots,m\}$.
 71	\end{lemma}
 72	\begin{proof}
 73		\uses{def:line-representative}
 74		Since $s$ is uniformly random in $\F_q$ and $m$ divides $q$, the index $i = \chi(s)$ is uniformly random in $\{1,2,\ldots,m\}$, so $(u_0,s)$ specifies a uniformly random axis-parallel line $\ell(u_0,e_i)$. Since $u_0 = L^{\mathrm{Ln}}_{e_i}(u)$ is the canonical representative of the line through $u$ in direction $e_i$, we have $u \in \ell(u_0,e_i)$.
 75	\end{proof}
 76	
 77	\begin{lemma}\label{lem:dlnf}
 78		\lean{MIPStarRE.QPBT.dLinePointDist_point_marginal_uniform, MIPStarRE.QPBT.dLinePointDist_mem_line, MIPStarRE.QPBT.dLinePointDist_prefix_zero}
 79		\leanok
 80		\uses{def:ld-question-distribution, def:line}
 81		Consider the pair $(\ell, u)$ sampled in the following way: first, sample the tuple $\bigl((u_0,s,v),(u,0,0)\bigr)$ from the CL distribution $\mu_{L_{\mathsf{DLine}}, L_{\mathsf{Point}}}$, and let $\ell = \ell(u_0, v)$ where $i = \chi(s)$. Then $u$ is a uniformly random point in $\F_q^m$, and $\ell$ is a random diagonal line that goes through $u$ and shares its first $i-1$ coordinates with $u$, for uniformly random $i \in \{1,2,\ldots,m\}$.
 82	\end{lemma}
 83	\begin{proof}
 84		\uses{lem:alnf}
 85		The proof is identical to that of Lemma~\ref{lem:alnf}: uniformity of $s$ makes $i = \chi(s)$ uniform, the direction component of the sampled tuple is $\pi_{i-1}(v)$ for uniform $v$ (so its first $i-1$ coordinates vanish), and $u_0 = L^{\mathrm{Ln}}_{\pi_{i-1}(v)}(u)$ places $u$ on the line $\ell(u_0,\pi_{i-1}(v))$.
 86	\end{proof}
